import express from 'express';
import path from 'path';
import { fileURLToPath } from 'url';
import fs from 'fs/promises';
import cors from 'cors';
import PocketBase from 'pocketbase';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const DB_CONFIG_FILE = path.join(__dirname, 'db_config.json');

const app = express();
const PORT = process.env.PORT || 3000;

// Configuration Fallback via Env (pour le premier démarrage)
const ENV_WEBHOOK_URL = process.env.WEBHOOK_URL;

// Instance globale PocketBase
let pb = null;

// Middleware
app.use(cors());
app.use(express.json({ limit: '10mb' }));
app.use(express.static(path.join(__dirname, 'dist')));

// --- GESTION CONFIGURATION POCKETBASE ---

async function getDbConfig() {
  try {
    const data = await fs.readFile(DB_CONFIG_FILE, 'utf8');
    return JSON.parse(data);
  } catch (e) {
    // Si pas de fichier de config local, on utilise les variables d'environnement
    return {
      url: process.env.POCKETBASE_URL,
      email: process.env.POCKETBASE_ADMIN_EMAIL,
      password: process.env.POCKETBASE_ADMIN_PASSWORD
    };
  }
}

async function saveDbConfig(config) {
  await fs.writeFile(DB_CONFIG_FILE, JSON.stringify(config, null, 2));
}

// Initialisation / Reconnexion dynamique
async function initPocketBase() {
  console.log('🔄 Initialisation connexion PocketBase...');
  const config = await getDbConfig();

  if (!config.url) {
    console.warn('⚠️ Aucune URL PocketBase configurée.');
    return false;
  }

  try {
    pb = new PocketBase(config.url);
    pb.autoCancellation(false); // Évite l'annulation des requêtes concurrentes

    if (config.email && config.password) {
      // Support PocketBase v0.23+ : Utilisation de la collection système _superusers
      await pb.collection('_superusers').authWithPassword(config.email, config.password);
      console.log(`✅ Connecté à PocketBase Admin (${config.url})`);
      return true;
    } else {
      console.warn('⚠️ Identifiants Admin manquants.');
      return false;
    }
  } catch (error) {
    console.error('❌ Erreur Connexion PocketBase:', error.originalError || error.message);
    return false;
  }
}

// Lancement initial
initPocketBase();

// --- API SYSTEME ---

// Lire la config actuelle (sans exposer le mot de passe complet si possible, mais ici requis pour l'UI)
app.get('/api/admin/db-config', async (req, res) => {
  const config = await getDbConfig();
  res.json({
    url: config.url || '',
    email: config.email || '',
    hasPassword: !!config.password // On indique juste si un mot de passe est set
  });
});

// Mettre à jour la config et reconnecter
app.post('/api/admin/db-config', async (req, res) => {
  try {
    const { url, email, password } = req.body;

    // On récupère l'ancienne config pour garder le mot de passe si non fourni
    const oldConfig = await getDbConfig();
    const newConfig = {
      url,
      email,
      password: password || oldConfig.password // Garder l'ancien si vide
    };

    await saveDbConfig(newConfig);
    const success = await initPocketBase();

    if (success) {
      res.json({ success: true, message: "Connexion établie et sauvegardée." });
    } else {
      res.status(400).json({ success: false, message: "Impossible de se connecter avec ces identifiants." });
    }
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// --- API METIER ---

/**
 * Middleware pour vérifier si PB est prêt
 */
const requirePb = (req, res, next) => {
  if (!pb || !pb.authStore.isValid) {
    return res.status(503).json({ error: "PocketBase non connecté. Vérifiez la configuration Admin." });
  }
  next();
};

app.get('/api/bootstrap', async (req, res) => {
  try {
    if (!pb) {
      // Mode dégradé si PB non configuré
      return res.json({ webhook_url: "", client_webhook_url: "", clients: [], poseurs: [] });
    }

    // Récupération parallèle avec gestion d'erreurs silencieuse
    const [clientsReq, poseursReq, configReq] = await Promise.all([
      pb.collection('clients').getFullList({ sort: 'nom' }).catch(() => []), 
      pb.collection('poseurs').getFullList({ sort: 'nom' }).catch(() => []),
      pb.collection('config').getFirstListItem('').catch(() => ({ webhook_url: "", client_webhook_url: "" }))
    ]);

    const finalWebhookUrl = configReq.webhook_url || ENV_WEBHOOK_URL || "http://default-webhook.com";
    const finalClientWebhookUrl = configReq.client_webhook_url || "";

    res.json({
      webhook_url: finalWebhookUrl,
      client_webhook_url: finalClientWebhookUrl,
      clients: clientsReq.map(c => ({ id: c.id, nom: c.nom, codeClient: c.codeClient, typeAffaire: c.typeAffaire })),
      poseurs: poseursReq.map(p => ({ id: p.id, nom: p.nom, entreprise: p.entreprise, telephone: p.telephone, specialite: p.specialite, codeSalarie: p.codeSalarie }))
    });
  } catch (error) {
    console.error('Erreur Bootstrap:', error);
    res.status(500).json({ error: "Erreur serveur" });
  }
});

// --- CRUD ---
app.post('/api/clients', requirePb, async (req, res) => {
  try { res.json(await pb.collection('clients').create(req.body)); } 
  catch (e) { res.status(500).json({ error: e.message }); }
});

app.put('/api/clients/:id', requirePb, async (req, res) => {
  try { res.json(await pb.collection('clients').update(req.params.id, req.body)); } 
  catch (e) { res.status(500).json({ error: e.message }); }
});

app.delete('/api/clients/:id', requirePb, async (req, res) => {
  try { await pb.collection('clients').delete(req.params.id); res.json({ success: true }); } 
  catch (e) { res.status(500).json({ error: e.message }); }
});

app.post('/api/poseurs', requirePb, async (req, res) => {
  try { res.json(await pb.collection('poseurs').create(req.body)); } 
  catch (e) { res.status(500).json({ error: e.message }); }
});

app.put('/api/poseurs/:id', requirePb, async (req, res) => {
  try { res.json(await pb.collection('poseurs').update(req.params.id, req.body)); } 
  catch (e) { res.status(500).json({ error: e.message }); }
});

app.delete('/api/poseurs/:id', requirePb, async (req, res) => {
  try { await pb.collection('poseurs').delete(req.params.id); res.json({ success: true }); } 
  catch (e) { res.status(500).json({ error: e.message }); }
});

app.post('/api/config', requirePb, async (req, res) => {
  try {
    let record;
    try {
      const existing = await pb.collection('config').getFirstListItem('');
      record = await pb.collection('config').update(existing.id, req.body);
    } catch (e) {
      record = await pb.collection('config').create(req.body);
    }
    res.json(record);
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// Support SPA
app.get('*', (req, res) => {
  res.sendFile(path.join(__dirname, 'dist', 'index.html'));
});

app.listen(PORT, () => {
  console.log(`🚀 Serveur BuildScan AI sur le port ${PORT}`);
});

import { Client, Poseur } from '../types';

export interface StorageConfig {
  webhook_url: string;
  client_webhook_url?: string;
  clients: Client[];
  poseurs: Poseur[];
}

export interface DbConfig {
  url: string;
  email: string;
  password?: string;
  hasPassword?: boolean;
}

// Fallback uniquement si le serveur est inaccessible et le cache vide
const DEFAULT_CONFIG: StorageConfig = {
  webhook_url: "",
  client_webhook_url: "",
  clients: [],
  poseurs: []
};

/**
 * Récupère la configuration complète (Bootstrap)
 */
export async function fetchStorageConfig(): Promise<StorageConfig | null> {
  try {
    const response = await fetch('/api/bootstrap');
    // Si 503, c'est que la DB n'est pas connectée, mais le serveur répond.
    // On veut quand même retourner null pour gérer l'état UI.
    if (!response.ok) throw new Error(`HTTP ${response.status}`);

    const config: StorageConfig = await response.json();

    // Mise à jour du cache local
    localStorage.setItem('buildscan_webhook_url', config.webhook_url);
    if (config.client_webhook_url) {
      localStorage.setItem('buildscan_client_webhook_url', config.client_webhook_url);
    }
    localStorage.setItem('buildscan_clients', JSON.stringify(config.clients));
    localStorage.setItem('buildscan_poseurs', JSON.stringify(config.poseurs));
    localStorage.setItem('buildscan_data_source', 'server');
    localStorage.setItem('buildscan_last_sync', new Date().toISOString());

    return config;
  } catch (err) {
    console.warn("API Inaccessible ou DB déconnectée, passage en mode cache/local :", err);

    const cachedWebhook = localStorage.getItem('buildscan_webhook_url');
    const cachedClientWebhook = localStorage.getItem('buildscan_client_webhook_url');
    const cachedClients = localStorage.getItem('buildscan_clients');
    const cachedPoseurs = localStorage.getItem('buildscan_poseurs');

    if (cachedWebhook || cachedClients) {
      const offlineConfig: StorageConfig = {
        webhook_url: cachedWebhook || "",
        client_webhook_url: cachedClientWebhook || "",
        clients: cachedClients ? JSON.parse(cachedClients) : [],
        poseurs: cachedPoseurs ? JSON.parse(cachedPoseurs) : []
      };

      localStorage.setItem('buildscan_data_source', 'local_cache');
      return offlineConfig;
    }

    return DEFAULT_CONFIG;
  }
}

// --- GESTION DB CONNECTION ---

export async function getDbConfig(): Promise<DbConfig | null> {
  try {
    const res = await fetch('/api/admin/db-config');
    if (!res.ok) return null;
    return await res.json();
  } catch (e) {
    return null;
  }
}

export async function updateDbConfig(config: DbConfig): Promise<{ success: boolean; message?: string }> {
  try {
    const res = await fetch('/api/admin/db-config', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(config)
    });
    const data = await res.json();
    return { success: res.ok && data.success, message: data.message || data.error };
  } catch (e: any) {
    return { success: false, message: e.message };
  }
}

// --- CRUD CLIENTS ---
export async function addClient(client: Omit<Client, 'id'>): Promise<Client | null> {
  try {
    const res = await fetch('/api/clients', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(client)
    });
    return res.ok ? await res.json() : null;
  } catch (e) { return null; }
}

export async function updateClient(id: string, client: Partial<Client>): Promise<boolean> {
  try {
    const res = await fetch(`/api/clients/${id}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(client)
    });
    return res.ok;
  } catch (e) { return false; }
}

export async function deleteClient(id: string): Promise<boolean> {
  try {
    const res = await fetch(`/api/clients/${id}`, { method: 'DELETE' });
    return res.ok;
  } catch (e) { return false; }
}

// --- CRUD POSEURS ---
export async function addPoseur(poseur: Omit<Poseur, 'id'>): Promise<Poseur | null> {
  try {
    const res = await fetch('/api/poseurs', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(poseur)
    });
    return res.ok ? await res.json() : null;
  } catch (e) { return null; }
}

export async function updatePoseur(id: string, poseur: Partial<Poseur>): Promise<boolean> {
  try {
    const res = await fetch(`/api/poseurs/${id}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(poseur)
    });
    return res.ok;
  } catch (e) { return false; }
}

export async function deletePoseur(id: string): Promise<boolean> {
  try {
    const res = await fetch(`/api/poseurs/${id}`, { method: 'DELETE' });
    return res.ok;
  } catch (e) { return false; }
}

// --- CONFIG WEBHOOKS ---
export async function updateConfig(config: Partial<StorageConfig>): Promise<boolean> {
  try {
    const res = await fetch('/api/config', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(config)
    });
    if (res.ok) {
      if (config.webhook_url !== undefined) localStorage.setItem('buildscan_webhook_url', config.webhook_url);
      if (config.client_webhook_url !== undefined) localStorage.setItem('buildscan_client_webhook_url', config.client_webhook_url);
    }
    return res.ok;
  } catch (e) { return false; }
}

// Deprecated: kept for backward compatibility if needed, but redirects to updateConfig
export async function updateWebhookUrl(url: string): Promise<boolean> {
  return updateConfig({ webhook_url: url });
}

import React, { useState, useEffect } from 'react';
import PocketBase from 'pocketbase';
import { fetchStorageConfig, updateConfig, getDbConfig, updateDbConfig, DbConfig } from '../services/configService';

const AdminSettings: React.FC = () => {
  // Webhook State
  const [webhookUrl, setWebhookUrl] = useState("");
  const [clientWebhookUrl, setClientWebhookUrl] = useState("");
  const [webhookSaving, setWebhookSaving] = useState(false);
  const [webhookStatus, setWebhookStatus] = useState<'idle' | 'success' | 'error'>('idle');

  // DB State
  const [dbConfig, setDbConfig] = useState<DbConfig>({ url: '', email: '', password: '' });
  const [dbSaving, setDbSaving] = useState(false);
  const [dbStatus, setDbStatus] = useState<'idle' | 'success' | 'error'>('idle');
  const [dbMessage, setDbMessage] = useState('');

  // Test Connection State
  const [isTesting, setIsTesting] = useState(false);
  const [testResult, setTestResult] = useState<{
    success: boolean;
    message?: string;
    jwt?: string;
    collections?: number;
  } | null>(null);

  useEffect(() => {
    loadConfigs();
  }, []);

  const loadConfigs = async () => {
    // Charger Webhooks (depuis DB)
    const storeConfig = await fetchStorageConfig();
    if (storeConfig) {
      setWebhookUrl(storeConfig.webhook_url || "");
      setClientWebhookUrl(storeConfig.client_webhook_url || "");
    }

    // Charger DB Config (depuis Serveur Local)
    const dbConf = await getDbConfig();
    if (dbConf) {
      setDbConfig({ 
        url: dbConf.url, 
        email: dbConf.email, 
        password: '', // On ne récupère jamais le mot de passe réel pour l'afficher
        hasPassword: dbConf.hasPassword 
      });
    }
  };

  const handleTestConnection = async () => {
    if (!dbConfig.url || !dbConfig.email || !dbConfig.password) {
      setTestResult({ success: false, message: "Veuillez remplir tous les champs (URL, Email, Mot de passe) pour tester." });
      return;
    }

    setIsTesting(true);
    setTestResult(null);

    try {
      // 1. Instanciation SDK PocketBase
      const pb = new PocketBase(dbConfig.url);
      pb.autoCancellation(false);

      // 2. Authentification Admin (Mise à jour pour PB v0.23+ : _superusers)
      const authData = await pb.collection('_superusers').authWithPassword(dbConfig.email, dbConfig.password);

      // 3. Test de lecture (Lister les collections pour vérifier les droits et la connectivité)
      const collections = await pb.collections.getFullList();

      setTestResult({
        success: true,
        message: "Connexion établie avec succès !",
        jwt: authData.token,
        collections: collections.length
      });

    } catch (err: any) {
      console.error("Test Connection Error:", err);
      let errorMsg = "Erreur inconnue";

      if (err.status === 0) errorMsg = "Impossible de joindre le serveur (Vérifiez l'URL ou CORS).";
      else if (err.status === 401 || err.status === 403) errorMsg = "Identifiants Admin invalides.";
      else if (err.status === 404) errorMsg = "URL invalide ou instance non trouvée.";
      else if (err.message) errorMsg = err.message;

      setTestResult({
        success: false,
        message: errorMsg
      });
    } finally {
      setIsTesting(false);
    }
  };

  const handleSaveWebhooks = async (e: React.FormEvent) => {
    e.preventDefault();
    setWebhookSaving(true);
    setWebhookStatus('idle');

    const success = await updateConfig({ 
      webhook_url: webhookUrl,
      client_webhook_url: clientWebhookUrl
    });

    if (success) {
      setWebhookStatus('success');
      setTimeout(() => setWebhookStatus('idle'), 3000);
    } else {
      setWebhookStatus('error');
    }
    setWebhookSaving(false);
  };

  const handleSaveDb = async (e: React.FormEvent) => {
    e.preventDefault();
    setDbSaving(true);
    setDbStatus('idle');
    setDbMessage('');

    const result = await updateDbConfig({
      url: dbConfig.url,
      email: dbConfig.email,
      password: dbConfig.password // Si vide, le serveur garde l'ancien
    });

    if (result.success) {
      setDbStatus('success');
      setDbMessage(result.message || 'Connexion réussie');
      setDbConfig(prev => ({ ...prev, password: '', hasPassword: true })); // Reset champ password
      // Recharger le webhook car la DB a pu changer
      const storeConfig = await fetchStorageConfig();
      if (storeConfig) {
        setWebhookUrl(storeConfig.webhook_url || "");
        setClientWebhookUrl(storeConfig.client_webhook_url || "");
      }
    } else {
      setDbStatus('error');
      setDbMessage(result.message || 'Erreur de connexion');
    }
    setDbSaving(false);
  };

  return (
    <div className="max-w-4xl mx-auto space-y-8 animate-in fade-in duration-500">

      {/* SECTION BASE DE DONNEES */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-8">
        <div className="flex items-center gap-4 mb-6 pb-6 border-b border-slate-100 justify-between">
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 bg-indigo-100 text-indigo-600 rounded-xl flex items-center justify-center text-xl shadow-inner">
              <i className="fas fa-database"></i>
            </div>
            <div>
              <h2 className="text-xl font-bold text-slate-800">Connexion PocketBase</h2>
              <p className="text-slate-500 text-xs">Configuration de l'instance SGBD cible</p>
            </div>
          </div>

          {/* Section STATUT Temps Réel (Résultat du dernier test) */}
          <div className={`px-4 py-2 rounded-lg border flex items-center gap-3 ${testResult?.success ? 'bg-emerald-50 border-emerald-200' : testResult?.success === false ? 'bg-red-50 border-red-200' : 'bg-slate-50 border-slate-200'}`}>
            <div className={`w-3 h-3 rounded-full ${testResult?.success ? 'bg-emerald-500 animate-pulse' : testResult?.success === false ? 'bg-red-500' : 'bg-slate-300'}`}></div>
            <div>
              <p className="text-[10px] font-black uppercase tracking-widest text-slate-500">Statut Backend</p>
              <p className={`text-xs font-bold ${testResult?.success ? 'text-emerald-700' : testResult?.success === false ? 'text-red-700' : 'text-slate-600'}`}>
                {testResult?.success ? 'En ligne' : testResult?.success === false ? 'Déconnecté' : 'Inconnu'}
              </p>
            </div>
          </div>
        </div>

        <form onSubmit={handleSaveDb} className="space-y-5">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
            <div className="col-span-2">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 block">URL Instance</label>
              <div className="relative">
                <i className="fas fa-globe absolute left-3 top-3.5 text-slate-400"></i>
                <input 
                  type="url" required
                  className="w-full pl-10 p-3 rounded-lg border border-slate-200 focus:ring-2 focus:ring-indigo-500 outline-none font-mono text-sm bg-slate-50"
                  placeholder="https://votre-instance.pockethost.io"
                  value={dbConfig.url}
                  onChange={e => setDbConfig({...dbConfig, url: e.target.value})}
                />
              </div>
            </div>

            <div>
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 block">Email Admin</label>
              <div className="relative">
                <i className="fas fa-envelope absolute left-3 top-3.5 text-slate-400"></i>
                <input 
                  type="email" required
                  className="w-full pl-10 p-3 rounded-lg border border-slate-200 focus:ring-2 focus:ring-indigo-500 outline-none text-sm bg-slate-50"
                  value={dbConfig.email}
                  onChange={e => setDbConfig({...dbConfig, email: e.target.value})}
                />
              </div>
            </div>

            <div>
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 block">
                Mot de Passe {dbConfig.hasPassword && <span className="text-emerald-500">(Configuré)</span>}
              </label>
              <div className="relative">
                <i className="fas fa-key absolute left-3 top-3.5 text-slate-400"></i>
                <input 
                  type="password"
                  className="w-full pl-10 p-3 rounded-lg border border-slate-200 focus:ring-2 focus:ring-indigo-500 outline-none text-sm bg-slate-50 placeholder:italic"
                  placeholder={dbConfig.hasPassword ? "•••••••• (Laisser vide pour garder)" : "Mot de passe Admin"}
                  value={dbConfig.password}
                  onChange={e => setDbConfig({...dbConfig, password: e.target.value})}
                />
              </div>
            </div>
          </div>

          {/* Zone de feedback Test */}
          {testResult && (
            <div className={`mt-4 p-4 rounded-lg border ${testResult.success ? 'bg-emerald-50 border-emerald-100' : 'bg-red-50 border-red-100'} animate-in slide-in-from-top-2`}>
              <div className="flex items-start gap-3">
                <i className={`fas ${testResult.success ? 'fa-check-circle text-emerald-500' : 'fa-times-circle text-red-500'} mt-1`}></i>
                <div className="w-full overflow-hidden">
                  <h4 className={`font-bold text-sm ${testResult.success ? 'text-emerald-800' : 'text-red-800'}`}>
                    {testResult.success ? 'Connexion réussie !' : 'Échec de la connexion'}
                  </h4>
                  <p className={`text-xs mt-1 ${testResult.success ? 'text-emerald-600' : 'text-red-600'}`}>{testResult.message}</p>

                  {testResult.success && testResult.jwt && (
                    <div className="mt-3 bg-white/50 p-2 rounded border border-emerald-200/50">
                      <div className="flex justify-between items-center mb-1">
                        <span className="text-[9px] font-bold text-emerald-700 uppercase">Token Admin (JWT)</span>
                        <span className="text-[9px] font-bold text-emerald-700 uppercase">{testResult.collections} Collections trouvées</span>
                      </div>
                      <code className="block font-mono text-[10px] text-emerald-600 break-all select-all">
                        {testResult.jwt.substring(0, 50)}...{testResult.jwt.substring(testResult.jwt.length - 10)}
                      </code>
                    </div>
                  )}
                </div>
              </div>
            </div>
          )}

          <div className="flex items-center justify-between pt-4 border-t border-slate-100 mt-4">
            <button
              type="button"
              onClick={handleTestConnection}
              disabled={isTesting}
              className={`px-4 py-2 rounded-lg font-bold text-sm transition-all flex items-center gap-2 border ${
                isTesting 
                  ? 'bg-slate-100 text-slate-400 border-slate-200' 
                  : 'bg-white text-indigo-600 border-indigo-200 hover:bg-indigo-50 hover:border-indigo-300'
              }`}
            >
              {isTesting ? (
                <><i className="fas fa-spinner fa-spin"></i> Test en cours...</>
              ) : (
                <><i className="fas fa-plug"></i> Tester la Connexion</>
              )}
            </button>

            <button 
              type="submit" 
              disabled={dbSaving}
              className={`px-6 py-2.5 rounded-xl font-bold transition-all flex items-center gap-2 shadow-sm ${
                dbSaving ? 'bg-slate-300 text-slate-500 cursor-not-allowed' : 'bg-slate-900 text-white hover:bg-slate-800 shadow-slate-300'
